import json
import itertools

def day_in_ranges(day, ranges):
    return any(start <= day <= end for start, end in ranges)

def compute_itinerary():
    # Input variables (constraints)
    total_days = 15
    cities = ["Paris", "Madrid", "Bucharest", "Seville"]
    required_stays = {
        "Paris": 6,
        "Madrid": 7,
        "Bucharest": 2,
        "Seville": 3,
    }
    # Must-be-in constraints (inclusive day ranges)
    must_be_in = {
        "Madrid": [(1, 7)],        # Attend show days 1-7 in Madrid
        "Bucharest": [(14, 15)],   # Visit relatives days 14-15 in Bucharest
    }
    # Direct flights (undirected)
    direct_edges = {
        frozenset(("Paris", "Bucharest")),
        frozenset(("Seville", "Paris")),
        frozenset(("Madrid", "Bucharest")),
        frozenset(("Madrid", "Paris")),
        frozenset(("Madrid", "Seville")),
    }
    def has_direct(a, b):
        return frozenset((a, b)) in direct_edges

    # Determine candidates for start (must include day 1) and end (must include day total_days)
    start_candidates = [c for c in cities if day_in_ranges(1, must_be_in.get(c, []))]
    end_candidates = [c for c in cities if day_in_ranges(total_days, must_be_in.get(c, []))]

    # Search sequences that satisfy direct flights and day constraints
    best_schedule = None
    for seq in itertools.permutations(cities, len(cities)):
        if start_candidates and seq[0] not in start_candidates:
            continue
        if end_candidates and seq[-1] not in end_candidates:
            continue
        # Check direct flights between consecutive cities
        if not all(has_direct(seq[i], seq[i+1]) for i in range(len(seq)-1)):
            continue
        # Verify sum of stays matches total_days with overlaps (k-1 flights)
        k = len(seq)
        if sum(required_stays[c] for c in seq) != total_days + (k - 1):
            continue

        # Build day ranges with 1-day overlaps on each transition (flight day)
        ranges = {}
        s = 1
        for i, c in enumerate(seq):
            if i == 0:
                e = s + required_stays[c] - 1
            else:
                s = prev_e  # overlap on flight day
                e = s + required_stays[c] - 1
            ranges[c] = (s, e)
            prev_e = e

        # Last city's end must be total_days
        if ranges[seq[-1]][1] != total_days:
            continue

        # Ensure must-be-in constraints satisfied
        ok = True
        for city, req_ranges in must_be_in.items():
            cs, ce = ranges[city]
            for rs, re in req_ranges:
                for d in range(rs, re + 1):
                    if not (cs <= d <= ce):
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                break
        if not ok:
            continue

        best_schedule = [(city, ranges[city][0], ranges[city][1]) for city in seq]
        break

    if not best_schedule:
        return {"itinerary": []}

    # Format output
    itinerary = []
    for city, s, e in best_schedule:
        itinerary.append({
            "day_range": f"Day {s}-{e}",
            "place": city
        })
    return {"itinerary": itinerary}

if __name__ == "__main__":
    result = compute_itinerary()
    print(json.dumps(result, ensure_ascii=False))
